#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
const long long MOD1=1000000007,MOD2=998244353;
const int maxk=7,base=1000000;
long long n,order;
int total;
int prefix_sum[maxk];
vector<int> seqs[maxk];

void build_sequences(int x,int length){
    order++, seqs[length].push_back(((order - x) % MOD2 + MOD2) % MOD2);
    prefix_sum[length]=(prefix_sum[length]+seqs[length].back())%MOD1;
    if(length==6) return;
    for(int d=0; d<=9; d++)
        build_sequences(x*10+d,length+1);
}

void traverse(long long x){
    if(x>n) return;
    if(x*base+base-1<=n && x*base*10>n){
        long long current_order=order;
        for(int i=0,mult=1;i<=6;i++,mult*=10){
            int sz=seqs[i].size();
            int diff=((current_order - x*mult) % MOD2 + MOD2) % MOD2;
            int pos=lower_bound(seqs[i].begin(),seqs[i].end(),MOD2 - diff)-seqs[i].begin();
            total=(total+1LL*diff*sz+prefix_sum[i])%MOD1;
            total=(total-1LL*MOD1*(sz - pos)%MOD1+MOD1)%MOD1;
            order+=sz;
        }
        return;
    }
    order++, total=(total+((order - x) % MOD2 + MOD2) % MOD2)%MOD1;
    for(int d=0; d<=9; d++)
        traverse(x*10+d);
}

int main(){
    scanf("%lld",&n);
    order=0; build_sequences(0,0);
    for(int i=0;i<=6;i++) sort(seqs[i].begin(),seqs[i].end());
    order=0;
    for(int i=1;i<=9;i++) traverse(i);
    printf("%d\n",total);
    return 0;
}
